### 问题描述

在使用`RopeWithSinCosCache`算子的过程中报错、
```
[ERROR] GE(2816287,test-mix-ops):2026-02-09-14:19:41.036.197 [node_checker_utils.cc:121]2816287 CalcSizeWithDimIndex: ErrorNo: 4294967295(failed) [COMP][MEM_ALLOC]Inner param dim_index value:0 invalid, bigger than dim size:0, shape:[], node: rope_concat_out_concat_3
```
查看dump图<a href="https://gitcode.com/user-attachments/files/8824148/a20e64d1c9c849a6b1e5c7d65cc1b0b0.txt" target="_blank">a20e64d1c9c849a6b1e5c7d65cc1b0b0.txt</a>发现`RopeWithSinCosCache`算子没有正确设置输出shape
实际调用代码如下
```
ge::Operator handle_qk_rope_op(
    ge::Graph &graph, struct ggml_tensor *node,
    std::map<struct ggml_tensor *, ge::Operator> &gmml_tensor_to_ge_op_map,
    int op_index, ggml_backend_cann_context &cann_ctx) {
    // 获取源张量
    struct ggml_tensor *src0 = node->src[0];  // 输入张量q
    struct ggml_tensor *src1 = node->src[1];  // 输入张量k
    struct ggml_tensor *src2 = node->src[2];  // 位置索引张量

    auto dst = node;
    int64_t head_dim = src0->ne[0];  // 特征维度
    int64_t num_q_heads = src0->ne[1];               // 注意力头数
    int64_t num_k_heads = src1->ne[1];               // 注意力头数
    int64_t seq_len = src0->ne[2];                    // 序列长度

    GGML_TENSOR_UNARY_OP_LOCALS  // 使用GGML宏获取输入张量的维度

    // 检查算子映射中是否存在输入
    ge::Operator op_x0;
    ge::Operator op_x1;
    ge::Operator op_pos;

    // 获取src0（主输入）操作符
    if (gmml_tensor_to_ge_op_map.find(src0) != gmml_tensor_to_ge_op_map.end()) {
        op_x0 = gmml_tensor_to_ge_op_map[src0];
    } else {
        printf("src0 not found in gmml_tensor_to_ge_op_map\n");
        assert(false);
    }

    // 获取src1（位置索引）操作符
    if (gmml_tensor_to_ge_op_map.find(src1) != gmml_tensor_to_ge_op_map.end()) {
        op_x1 = gmml_tensor_to_ge_op_map[src1];
    } else {
        printf("src1 not found in gmml_tensor_to_ge_op_map\n");
        assert(false);
    }

    if (gmml_tensor_to_ge_op_map.find(src2) != gmml_tensor_to_ge_op_map.end()) {
        op_pos = gmml_tensor_to_ge_op_map[src2];
    } else {
        printf("src2 not found in gmml_tensor_to_ge_op_map\n");
        assert(false);
    }

    ge::Operator op_x0_reshape = create_reshape_op(
        graph, "rope_qk_reshape_x0_", "_" + std::to_string(op_index), op_x0,
        std::vector<int64_t>{seq_len, head_dim * num_q_heads});
    ge::Operator op_x1_reshape = create_reshape_op(
        graph, "rope_qk_reshape_x1_", "_" + std::to_string(op_index), op_x1,
        std::vector<int64_t>{seq_len, head_dim * num_k_heads});

    // 第三步：执行RoPE操作
    // TODO: 在同一个模型中多个RoPE也可能共享一个sin、cos缓存
    std::string curr_suffix = "_" + std::to_string(op_index);
    RopeCache rope_cache(cann_ctx, dst);
    ge::Operator rope_sin_cache =
        rope_cache.GetSinOp(graph, "rope_sin_tensor" + curr_suffix);
    ge::Operator rope_cos_cache =
        rope_cache.GetCosOp(graph, "rope_cos_tensor" + curr_suffix);

    ge::Operator op_pos_squeeze = create_squeeze_op(
        graph, "rope_squeeze_pos_", curr_suffix, op_pos, {0, 1, 2});

    ge::Operator cos_sin_cache = create_concat_op(
        graph, "rope_cos_sin_cache_", curr_suffix, {rope_cos_cache, rope_sin_cache},
        3);
    ge::Operator cos_sin_cache_reshape = create_reshape_op(
        graph, "rope_cos_sin_cache_", curr_suffix, cos_sin_cache,
        std::vector<int64_t>{cann_ctx.n_ctx, head_dim});
    std::string name_rope = "rope_rope" + curr_suffix;
    ge::op::RopeWithSinCosCache rope_op(name_rope.c_str());
    rope_op.set_input_positions(op_pos_squeeze)  // 位置索引输入
    .set_input_queryIn(op_x0_reshape)                 // 主输入（查询向量）
    .set_input_keyIn(op_x1_reshape)
    .set_input_cosSinCache(cos_sin_cache_reshape)
    .set_attr_numQHeads(num_q_heads)  // 注意力头数
    .set_attr_numKHeads(num_k_heads)
    .set_attr_headSize(head_dim)        // 每个头的大小
    .set_attr_isNeoxStyle(false);

    rope_op.update_output_desc_queryOut(ge::TensorDesc(ge::Shape({seq_len, head_dim * num_q_heads}), ge::FORMAT_ND, get_data_type(node->type)));
    rope_op.update_output_desc_keyOut(ge::TensorDesc(ge::Shape({seq_len, head_dim * num_k_heads}), ge::FORMAT_ND, get_data_type(node->type)));

    ge::Operator query_out = create_identity_op_by_name(graph, "rope_query_out_", curr_suffix, rope_op, "queryOut");
    ge::Operator key_out = create_identity_op_by_name(graph, "rope_key_out_", curr_suffix, rope_op, "keyOut");

    ge::Operator query_out_reshape = create_reshape_op(
        graph, "rope_qk_query_reshape_out_", curr_suffix, query_out,
        std::vector<int64_t>{1, seq_len, num_q_heads, head_dim});
    ge::Operator key_out_reshape = create_reshape_op(
        graph, "rope_qk_key_reshape_out_", curr_suffix, key_out,
        std::vector<int64_t>{1, seq_len, num_k_heads, head_dim});

    ge::Operator concat_out = create_concat_op(graph, "rope_concat_out_", curr_suffix, {query_out_reshape, key_out_reshape}, 1);

    std::vector<int64_t> output_shape = build_output_shape(node);
    ge::DataType dataType = get_data_type(node->type);
    ge::TensorDesc desc_out(ge::Shape(output_shape), ge::FORMAT_ND, dataType);
    concat_out.UpdateOutputDesc("y", desc_out);

    // 返回最终操作
    return concat_out;
}
```
