+    ASSERT_NE(built, nullptr);
+    descriptor_ = built->message_type(0);
+    message_.reset(factory_.GetPrototype(descriptor_)->New());
+  }
+
+  static void AddField(google::protobuf::DescriptorProto *message, const char *name, int number,
+                       google::protobuf::FieldDescriptorProto::Type type, bool repeated) {
+    auto *field = message->add_field();
+    field->set_name(name);
+    field->set_number(number);
+    field->set_type(type);
+    field->set_label(repeated ? google::protobuf::FieldDescriptorProto::LABEL_REPEATED
+                              : google::protobuf::FieldDescriptorProto::LABEL_OPTIONAL);
+  }
+
+  const ProtobufFieldDescriptor *Field(const char *name) const {
+    return descriptor_->FindFieldByName(name);
+  }
