+  std::unique_ptr<ProtobufMsg> message_;
+};
+
+TEST_F(Pb2JsonPrecision, AdjacentScalarFloatsRemainDistinct) {
+  CheckFloat(1.2345678806304932F);
+  const auto first = Convert().at("f");
+  CheckFloat(std::nextafter(1.2345678806304932F, 2.0F));
+  EXPECT_NE(first, Convert().at("f"));
+}
+
+TEST_F(Pb2JsonPrecision, ScalarFloatBoundariesPreserveBitsAndStringType) {
+  for (float value : {0.0F, -0.0F, 1.0F, -1.0F, std::numeric_limits<float>::denorm_min(),
+                     -std::numeric_limits<float>::denorm_min(), std::numeric_limits<float>::min(),
+                     -std::numeric_limits<float>::min(), std::numeric_limits<float>::max(),
+                     -std::numeric_limits<float>::max()}) {
+    CheckFloat(value);
+  }
+}
+
+TEST_F(Pb2JsonPrecision, SampledFiniteScalarFloatsPreserveBits) {
+  uint32_t bits = 0x9e3779b9U;
+  for (int i = 0; i < 2048; ++i) {
+    bits = bits * 1664525U + 1013904223U;
+    float value;
+    std::memcpy(&value, &bits, sizeof(value));
+    if (std::isfinite(value)) {
+      CheckFloat(value);
+    }
+  }
+}
+
+TEST_F(Pb2JsonPrecision, RepeatedFiniteDoublesPreserveBitsIncludingNegativeZero) {
+  const std::vector<double> values = {0.12345678901234568, -0.0, 1.0000000000000002,
+      std::numeric_limits<double>::denorm_min(), -std::numeric_limits<double>::min(),
+      std::numeric_limits<double>::max(), -std::numeric_limits<double>::max()};
+  for (double value : values) {
+    message_->GetReflection()->AddDouble(message_.get(), Field("doubles"), value);
+  }
+  const Json json = Convert();
+  ASSERT_EQ(json.at("doubles").size(), values.size());
+  for (size_t i = 0; i < values.size(); ++i) {
+    ASSERT_TRUE(json.at("doubles").at(i).is_number_float());
+    EXPECT_EQ(PrecisionBits<uint64_t>(json.at("doubles").at(i).get<double>()),
+              PrecisionBits<uint64_t>(values[i]));
+  }
+}
+
+TEST_F(Pb2JsonPrecision, ScalarFiniteDoubleIsPresentAndPreservesBits) {
+  for (double value : {0.12345678901234568, -0.0, 1.0000000000000002,
+                       std::numeric_limits<double>::min(), std::numeric_limits<double>::max()}) {
+    message_->GetReflection()->SetDouble(message_.get(), Field("d"), value);
+    const Json json = Convert();
+    ASSERT_TRUE(json.contains("d"));
+    ASSERT_TRUE(json.at("d").is_number_float());
+    EXPECT_EQ(PrecisionBits<uint64_t>(json.at("d").get<double>()), PrecisionBits<uint64_t>(value));
+  }
+}
+
+TEST_F(Pb2JsonPrecision, RepeatedFloatAndInt64ControlsRemainExact) {
+  const std::vector<float> floats = {0.123456789F, -0.0F, std::nextafter(1.0F, 2.0F)};
+  const std::vector<int64_t> integers = {std::numeric_limits<int64_t>::min(),
+      std::numeric_limits<int64_t>::max(), 9007199254740993LL};
+  for (float v : floats) {
+    message_->GetReflection()->AddFloat(message_.get(), Field("floats"), v);
+  }
+  for (int64_t v : integers) {
+    message_->GetReflection()->AddInt64(message_.get(), Field("integers"), v);
+  }
+  const Json json = Convert();
+  ASSERT_EQ(json.at("floats").size(), floats.size());
+  EXPECT_EQ(json.at("integers").get<std::vector<int64_t>>(), integers);
+  for (size_t i = 0; i < floats.size(); ++i) {
+    EXPECT_EQ(PrecisionBits<uint32_t>(json.at("floats").at(i).get<float>()), PrecisionBits<uint32_t>(floats[i]));
+  }
+}
+
+TEST_F(Pb2JsonPrecision, UnsetAndBlacklistedFieldsStayAbsent) {
+  EXPECT_TRUE(Convert().is_null());
+  message_->GetReflection()->SetFloat(message_.get(), Field("f"), 1.23456789F);
+  message_->GetReflection()->AddDouble(message_.get(), Field("doubles"), -0.0);
+  Json json;
+  Pb2Json::Message2Json(*message_, {"f", "doubles"}, json);
+  EXPECT_TRUE(json.is_null());
+}
+
+TEST_F(Pb2JsonPrecision, ScalarNonfiniteClassesKeepExistingStringContract) {
+  for (float value : {std::numeric_limits<float>::infinity(),
+                     -std::numeric_limits<float>::infinity(), std::numeric_limits<float>::quiet_NaN()}) {
+    message_->GetReflection()->SetFloat(message_.get(), Field("f"), value);
+    const Json json = Convert();
+    ASSERT_TRUE(json.at("f").is_string());
+    const float restored = std::strtof(json.at("f").get<std::string>().c_str(), nullptr);
+    if (std::isnan(value)) {
+      EXPECT_TRUE(std::isnan(restored));
+    } else {
+      EXPECT_TRUE(std::isinf(restored));
+      EXPECT_EQ(std::signbit(restored), std::signbit(value));
+    }
+  }
+}
+}  // namespace
+}  // namespace ge
